const refreshNow = () => run(true);
async function guard(el, fn) {
  if (el) el.disabled = true;
  try { await fn(); } catch (e) { if (e.status !== 401) toast(e.message, 'err'); } finally { if (el && el.isConnected) el.disabled = false; }
}
